                    .filter(Objects::nonNull).reduce(BigDecimal.ZERO, BigDecimal::add) : null;
            return new PersonView(person.getId(), person.getName(), grade,
                    claims.stream().map(c -> ClaimView.of(c, grade, rates)).toList(), money(claimed),
