export class Home {
  protected readonly session = inject(Session);
  protected readonly nameInput = signal('');
  protected readonly sheetInput = signal('');
  protected readonly signinError = signal('');
  protected readonly sheetError = signal('');
  protected readonly todayInput = signal('');

  protected value(e: Event): string {
    return (e.target as HTMLInputElement).value;
  }

  protected async signIn(e: Event): Promise<void> {
    e.preventDefault();
    this.signinError.set('');
    const name = this.nameInput().trim();
    if (!name) {
      this.signinError.set('Enter a name.');
      return;
    }
    try {
      await this.session.signIn(name);
    } catch {
      this.signinError.set('Could not sign in.');
    }
  }

  protected async load(e: Event): Promise<void> {
    e.preventDefault();
    this.sheetError.set('');
    const id = this.sheetInput().trim();
    if (!id) {
      this.sheetError.set('Enter a sheet id.');
      return;
    }
    try {
      await this.session.loadSheet(id);
    } catch {
      this.sheetError.set('Could not load the sheet.');
    }
  }

  protected async saveToday(e: Event): Promise<void> {
    e.preventDefault();
    this.sheetError.set('');
    const today = this.todayInput().trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(today)) {
      this.sheetError.set('Enter a date for today.');
      return;
    }
    try {
      await this.session.setToday(today);
    } catch {
      this.sheetError.set('Could not change today.');
    }
  }
}
      if (r.from === null || r.from <= today) inForce[r.grade] = r.pct;
    }
    return inForce;
  });
  protected readonly grade = signal('A');
  protected readonly pct = signal('');
  protected readonly from = signal('');
  protected readonly error = signal('');

  constructor() {
    effect(() => {
      const sheet = this.session.sheet();
      this.session.loads();
      this.rates.set([]);
      this.grade.set('A');
      this.pct.set('');
      this.from.set('');
      this.error.set('');
      if (sheet) void this.reload(sheet);
    });
  }

  protected value(e: Event): string {
    return (e.target as HTMLInputElement | HTMLSelectElement).value;
  }

  protected async save(e: Event): Promise<void> {
    e.preventDefault();
    this.error.set('');
    const sheet = this.session.sheet();
    if (!sheet) return;
    const grade = this.grade();
    const pct = this.pct().trim();
    const from = this.from().trim();
    if (!GRADES.includes(grade)) {
      this.error.set('Choose a grade.');
      return;
    }
    if (!PCT.test(pct)) {
      this.error.set('Enter a rate of 0.00 or more, with up to two decimals.');
      return;
    }
    if (from !== '' && !DATE.test(from)) {
      this.error.set('Enter a from-date, or leave it blank for from the start.');
      return;
    }
    const headers = { 'X-User': this.session.user() ?? '' };
    try {
      const saved = await firstValueFrom(
        this.http.put<Rate>(`/api/sheets/${encodeURIComponent(sheet)}/rates/${grade}`, { pct, from: from === '' ? null : from }, { headers }),
      );
      if (this.session.sheet() !== sheet) return;
      this.rates.update((rs) =>
        [...rs.filter((r) => r.grade !== saved.grade || r.from !== saved.from), saved].sort(byGradeAndFrom),
      );
      this.pct.set('');
      this.from.set('');
      this.changed.emit();
    } catch {
      if (this.session.sheet() !== sheet) return;
      this.error.set('Could not set the rate.');
    }
  }

  private async reload(sheet: string): Promise<void> {
    const loads = this.session.loads();
    const rates = await firstValueFrom(this.http.get<Rate[]>(`/api/sheets/${encodeURIComponent(sheet)}/rates`));
    if (this.session.sheet() === sheet && this.session.loads() === loads) this.rates.set(rates);
  }
}
package net.officefloor.hq.app;

import java.math.RoundingMode;
import net.officefloor.hq.app.claim.ClaimChanged;
import net.officefloor.hq.app.person.PersonChanged;
import net.officefloor.hq.app.rate.RateChanged;
import org.springframework.stereotype.Component;
import org.springframework.transaction.event.TransactionalEventListener;

/**
 * Writes one audit line per change to a sheet, once the change is committed: a refused change
 * rolls back and writes nothing. Each line is the event, {@code sheet=} and {@code by=}, then the
 * event's fields.
 */
@Component
public class SheetAudit {

    private final Audit audit;

    public SheetAudit(Audit audit) {
        this.audit = audit;
    }

    @TransactionalEventListener
    public void on(PersonChanged e) {
        audit.record(e.event() + " sheet=" + e.sheetId() + " by=" + e.user()
                + " name=" + e.name() + " grade=" + e.grade());
    }

    @TransactionalEventListener
    public void on(ClaimChanged e) {
        audit.record(e.event() + " sheet=" + e.sheetId() + " by=" + e.user()
                + " person=" + e.person() + " amount=" + e.amount().setScale(2, RoundingMode.HALF_UP).toPlainString()
                + " date=" + e.date() + (e.number() == null ? "" : " number=" + e.number())
                + (e.due() == null ? "" : " due=" + e.due()));
    }

    @TransactionalEventListener
    public void on(RateChanged e) {
        audit.record("RATE_SET sheet=" + e.sheetId() + " by=" + e.user()
                + " grade=" + e.grade() + " rate=" + e.rate().setScale(2, RoundingMode.HALF_UP).toPlainString()
                + (e.from() == null ? "" : " from=" + e.from()));
    }
}
